// added to RunErrorCode (src/analyze/orchestrator/types.ts) and to the daemon's context error codes
| 'no-plan-for-request'   // the plan for this request has nothing in it
| 'answer-step-failed'    // the answer-writing step failed; data carries the lookup results and the report (raised by Story s1)
| 'run-abandoned'         // a record left in progress with no live run behind it (raised by Story s7)
// 'aborted' exists in RunErrorCode; Story s4 adds it to AnalyzeRpcErrorCode with cancellation
// RunFailure { code, message, data? } and RunStage are unchanged

api.signature:
// replaced, together with inferScopePath, by one exported function in a new module src/analyze/context/scope.ts
function resolveScope(ref: AnalyzeScopeRef, deps?: ScopeDeps): Promise<ResolvedScope>

interface ResolvedScope {
  readonly kind: AnalyzeScopeRef['kind'];
  readonly value: string;                 // as given
  readonly repoPath: string | null;       // the registered repo that contains the scope (longest prefix), or the connection's repo; null when none is registered
  readonly lookupPath: string;            // the directory lookups run in: repoPath when known, else the scope's own directory
  readonly filePath?: string;             // file and symbol
  readonly entityId?: string;             // symbol
  readonly entityName?: string;           // symbol
  readonly connectionId?: string;         // connection
}
interface ScopeDeps { listRepos(): Promise<readonly RegisteredRepo[]>; findEntitiesByFile(file: string): Promise<readonly Entity[]>; loadConnections(repoPath: string): Promise<LoadedConnections>; }
